    Properties props = new Properties();
    props.setProperty(HoodieMetadataConfig.STREAMING_WRITE_ENABLED.key(), "true");
    props.setProperty(HoodieTableConfig.TYPE.key(), HoodieTableType.MERGE_ON_READ.name());
