private HoodieTableMetaClient prepareMetaClient(List<HoodieInstant> activeInstants, List<HoodieInstant> archivedInstants, String startTs) throws IOException {
    HoodieTableMetaClient mockMetaClient = mock(HoodieTableMetaClient.class);
    HoodieArchivedTimeline mockArchivedTimeline = mock(HoodieArchivedTimeline.class);
    HoodieTableConfig mockTableConfig = mock(HoodieTableConfig.class);
    when(mockMetaClient.getBasePath()).thenReturn(new StoragePath("file://dummy/path"));
    when(mockMetaClient.scanHoodieInstantsFromFileSystem(any(), any(), eq(true))).thenReturn(activeInstants);
    when(mockMetaClient.getMetaPath()).thenReturn(new StoragePath("file://dummy/path/.hoodie"));
    when(mockMetaClient.getTableConfig()).thenReturn(mockTableConfig);
    when(mockMetaClient.getTableConfig().getTimelinePath()).thenReturn("timeline");
    HoodieActiveTimeline activeTimeline = new ActiveTimelineV2(mockMetaClient);
    when(mockMetaClient.getActiveTimeline()).thenReturn(activeTimeline);
    Set<String> validWriteActions = CollectionUtils.createSet(COMMIT_ACTION, DELTA_COMMIT_ACTION, COMPACTION_ACTION, LOG_COMPACTION_ACTION, REPLACE_COMMIT_ACTION);
    when(mockMetaClient.getArchivedTimeline(any())).thenReturn(mockArchivedTimeline);
    HoodieTimeline mergedTimeline = new BaseTimelineV2(archivedInstants.stream().filter(instant -> instant.requestedTime().compareTo(startTs) >= 0), null).mergeTimeline(activeTimeline);
    when(mockArchivedTimeline.mergeTimeline(eq(activeTimeline))).thenReturn(mergedTimeline);
    HoodieTimeline mergedWriteTimeline = new BaseTimelineV2(archivedInstants.stream().filter(instant -> instant.requestedTime().compareTo(startTs) >= 0), null).mergeTimeline(activeTimeline.getWriteTimeline());
    when(mockArchivedTimeline.mergeTimeline(argThat(timeline -> timeline.filter(instant -> instant.getAction().equals(ROLLBACK_ACTION)).countInstants() == 0))).thenReturn(mergedWriteTimeline);
    return mockMetaClient;
}

