    HoodieTableMetaClient mockedMetaClient = mock(HoodieTableMetaClient.class);
    HoodieTable<?, ?, ?, ?> mockHoodieTable = mock(HoodieTable.class);
    when(mockHoodieTable.getMetaClient()).thenReturn(mockedMetaClient);
