    AWSGlueCatalogSyncClient clientWithTags = new AWSGlueCatalogSyncClient(mockAwsGlue, mockSts, new HiveSyncConfig(props), GlueTestUtil.getMetaClient());
    // Mock table does not exist (for createTable to proceed)
    CompletableFuture<GetTableResponse> tableNotFoundFuture = mock(CompletableFuture.class);
